-- Add extra community seed data without creating new user accounts.
-- Community rows require technical profile rows because community.profile_id is mandatory.
DO $$
DECLARE
  comm RECORD;
  post_rec RECORD;
  media_urls TEXT[];
  fallback_media_urls TEXT[];
  has_post_media BOOLEAN;
  media_count INT;
  sort_idx INT;
  candidate_idx INT;
  selected_count INT;
  candidate_count INT;
  url TEXT;
  used_media_urls TEXT[] := ARRAY[]::TEXT[];
  cprof_id BIGINT;
  comm_id BIGINT;
  cover_id BIGINT;
  post_id BIGINT;
  media_id BIGINT;
  member_profile_id BIGINT;
  community_ids BIGINT[] := ARRAY[]::BIGINT[];
  post_ids BIGINT[] := ARRAY[]::BIGINT[];
BEGIN
  CREATE TEMP TABLE seed_more_community_spec (
    ord INT PRIMARY KEY,
    username TEXT NOT NULL,
    title TEXT NOT NULL,
    bio TEXT NOT NULL,
    cover_url TEXT NOT NULL
  ) ON COMMIT DROP;

  CREATE TEMP TABLE seed_more_community_media (
    username TEXT PRIMARY KEY,
    urls TEXT[] NOT NULL
  ) ON COMMIT DROP;

  CREATE TEMP TABLE seed_more_community_post_media (
    username TEXT NOT NULL,
    post_idx INT NOT NULL,
    urls TEXT[] NOT NULL,
    PRIMARY KEY (username, post_idx)
  ) ON COMMIT DROP;

  CREATE TEMP TABLE seed_more_community_post (
    username TEXT NOT NULL,
    post_idx INT NOT NULL,
    post_text TEXT NOT NULL,
    PRIMARY KEY (username, post_idx)
  ) ON COMMIT DROP;





  FOR comm IN
    SELECT * FROM seed_more_community_spec ORDER BY ord
  LOOP
    IF EXISTS (SELECT 1 FROM community WHERE username = comm.username) THEN
      CONTINUE;
    END IF;

    VALUES (gen_random_uuid())
    RETURNING id INTO cprof_id;

    VALUES (
      gen_random_uuid(),
      comm.username || '_cover',
      cprof_id,
      CASE WHEN comm.cover_url LIKE '%.png' THEN 'png' WHEN comm.cover_url LIKE '%.jpeg' THEN 'jpeg' ELSE 'jpg' END,
      CASE WHEN comm.cover_url LIKE '%.png' THEN 'image/png' ELSE 'image/jpeg' END,
      comm.cover_url,
      0
    )
    RETURNING id INTO cover_id;

    UPDATE profile SET avatar_id = cover_id WHERE id = cprof_id;

    VALUES (gen_random_uuid(), comm.title, comm.bio, 'public', cprof_id, comm.username, cover_id)
    RETURNING id INTO comm_id;

    community_ids := community_ids || comm_id;

    FOR member_profile_id IN
      SELECT up.profile_id
      FROM user_profile up
      JOIN user_account ua ON ua.id = up.user_account_id
      WHERE ua.is_active = TRUE AND up.is_active = TRUE
      ORDER BY ((up.profile_id * 37 + comm.ord * 11) % 997), up.profile_id
      LIMIT 18
    LOOP
      VALUES (
        gen_random_uuid(),
        member_profile_id,
        comm_id,
        CASE WHEN member_profile_id = (
          SELECT up.profile_id
          FROM user_profile up
          JOIN user_account ua ON ua.id = up.user_account_id
          WHERE ua.is_active = TRUE AND up.is_active = TRUE
          ORDER BY ((up.profile_id * 37 + comm.ord * 11) % 997), up.profile_id
          LIMIT 1
        ) THEN 'moderator' ELSE 'member' END::community_member_role
      )
      ON CONFLICT (profile_id, community_id) DO NOTHING;
    END LOOP;

    SELECT urls INTO fallback_media_urls
    FROM seed_more_community_media
    WHERE username = comm.username;

    FOR post_rec IN
      SELECT * FROM seed_more_community_post WHERE username = comm.username ORDER BY post_idx
    LOOP
      VALUES (
        gen_random_uuid(),
        post_rec.post_text,
        cprof_id,
        comm_id,
        FALSE,
        TRUE,
        NOW() - ((comm.ord * 8 + post_rec.post_idx) || ' hours')::INTERVAL,
        NOW() - ((comm.ord * 8 + post_rec.post_idx) || ' hours')::INTERVAL
      )
      RETURNING id INTO post_id;

      post_ids := post_ids || post_id;

      SELECT urls INTO media_urls
      FROM seed_more_community_post_media
      WHERE username = comm.username AND post_idx = post_rec.post_idx;

      has_post_media := media_urls IS NOT NULL;
      IF has_post_media THEN
        media_urls := media_urls || fallback_media_urls;
      ELSE
        media_urls := fallback_media_urls;
      END IF;

      media_count := LEAST(
        array_length(media_urls, 1),
        CASE
          WHEN has_post_media AND array_length(media_urls, 1) >= 3 AND ((comm.ord + post_rec.post_idx) % 4 = 0) THEN 3
          WHEN has_post_media AND array_length(media_urls, 1) >= 2 THEN 2
          WHEN ((comm.ord + post_rec.post_idx) % 4 = 0) THEN 2
          ELSE 1
        END
      );

      selected_count := 0;
      candidate_count := array_length(media_urls, 1);

      FOR candidate_idx IN 0..(candidate_count - 1) LOOP
        EXIT WHEN selected_count >= media_count;

        IF has_post_media THEN
          url := media_urls[candidate_idx + 1];
        ELSE
          url := media_urls[((post_rec.post_idx + candidate_idx - 1) % candidate_count) + 1];
        END IF;

        IF url = ANY(used_media_urls) THEN
          CONTINUE;
        END IF;

        VALUES (
          gen_random_uuid(),
          comm.username || '_post_' || post_rec.post_idx || '_' || selected_count,
          cprof_id,
          CASE WHEN url LIKE '%.png' THEN 'png' WHEN url LIKE '%.jpeg' THEN 'jpeg' ELSE 'jpg' END,
          CASE WHEN url LIKE '%.png' THEN 'image/png' ELSE 'image/jpeg' END,
          url,
          0
        )
        RETURNING id INTO media_id;

        used_media_urls := used_media_urls || url;

        VALUES (post_id, media_id, selected_count);

        selected_count := selected_count + 1;
      END LOOP;

      IF selected_count = 0 AND candidate_count > 0 THEN
        IF has_post_media THEN
          url := media_urls[1];
        ELSE
          url := media_urls[((post_rec.post_idx - 1) % candidate_count) + 1];
        END IF;

        VALUES (
          gen_random_uuid(),
          comm.username || '_post_' || post_rec.post_idx || '_0',
          cprof_id,
          CASE WHEN url LIKE '%.png' THEN 'png' WHEN url LIKE '%.jpeg' THEN 'jpeg' ELSE 'jpg' END,
          CASE WHEN url LIKE '%.png' THEN 'image/png' ELSE 'image/jpeg' END,
          url,
          0
        )
        RETURNING id INTO media_id;

        VALUES (post_id, media_id, 0);
      END IF;
    END LOOP;
  END LOOP;

  SELECT 'community', unnest(community_ids), 'upsert'
  WHERE array_length(community_ids, 1) IS NOT NULL;

  SELECT 'post', unnest(post_ids), 'upsert'
  WHERE array_length(post_ids, 1) IS NOT NULL;
END $$;
